class TrieNode:
    def __init__(self):
        self.children = {}
        # Track: (word length, index in wordsContainer)
        self.min_len = float('inf')
        self.min_idx = -1

def longestCommonSuffixQueries(wordsContainer, wordsQuery):
    # Build a trie of reversed wordsContainer
    root = TrieNode()
    for idx, word in enumerate(wordsContainer):
        node = root
        # The root stands for the empty suffix, which every word shares
        if len(word) < node.min_len:
            node.min_len = len(word)
            node.min_idx = idx
        for ch in reversed(word):
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            # Words are inserted in index order, so a strictly shorter word is the
            # only better candidate (equal length keeps the earlier index)
            if len(word) < node.min_len:
                node.min_len = len(word)
                node.min_idx = idx

    result = []
    for query in wordsQuery:
        node = root
        # Even with no matching suffix, every word shares the empty suffix
        best_idx = root.min_idx
        for ch in reversed(query):
            if ch not in node.children:
                break
            node = node.children[ch]
            best_idx = node.min_idx  # deeper node = longer common suffix
        result.append(best_idx)
    return result
